#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum BoundedLatticeInstanceCompleteness {
    NotBoundedLatticeInstance,
    BoundedLatticeComplete,
    BoundedLatticePartial {
        missing: BoundedLatticeMissingWitness,
    },
}
impl BoundedLatticeInstanceCompleteness {
    pub fn missing(&self) -> BoundedLatticeMissingWitness {
        match self {
            BoundedLatticeInstanceCompleteness::NotBoundedLatticeInstance => {
                panic!("no missing on unit variant")
            }
            BoundedLatticeInstanceCompleteness::BoundedLatticeComplete => {
                panic!("no missing on unit variant")
            }
            BoundedLatticeInstanceCompleteness::BoundedLatticePartial {
                missing: __val, ..
            } => __val.clone(),
        }
    }
}

