pub fn is_empty<T: Clone>(xs: Rc<Vec<T>>) -> bool {
    match xs.clone() {
        FreeMonoid::Empty => true,
        FreeMonoid::Cons { .. } => false,
    }
}

pub fn non_empty<T: Clone>(xs: Rc<Vec<T>>) -> bool {
    match is_empty(xs.clone()) {
        true => false,
        false => true,
    }
}

pub fn length<T: Clone>(xs: Rc<Vec<T>>) -> i64 {
    fold_list(xs.clone(), 0, |count, _| (count.clone() + 1))
}

pub fn for_all<T: Clone>(xs: Rc<Vec<T>>, predicate: impl Fn(T) -> bool + Clone) -> bool {
    fold_list(xs.clone(), true, |acc, item| match acc.clone() {
        true => predicate(item.clone()),
        false => false,
    })
}

pub fn any<T: Clone>(xs: Rc<Vec<T>>, predicate: impl Fn(T) -> bool + Clone) -> bool {
    fold_list(xs.clone(), false, |acc, item| match acc.clone() {
        true => true,
        false => predicate(item.clone()),
    })
}

pub fn filter<T: Clone>(xs: Rc<Vec<T>>, predicate: impl Fn(T) -> bool + Clone) -> Rc<Vec<T>> {
    fold_list_right(xs.clone(), Rc::new(vec![]), |acc, item| {
        match predicate(item.clone()) {
            true => Rc::new({
                let mut __cons_v = (*acc.clone()).clone();
                __cons_v.insert(0, item.clone());
                __cons_v
            }),
            false => acc.clone(),
        }
    })
}

pub fn contains<T: Clone>(xs: Rc<Vec<T>>, item: T, eq: impl Fn(T, T) -> bool + Clone) -> bool {
    any(xs.clone(), |candidate| eq(candidate.clone(), item.clone()))
}

pub fn count_where<T: Clone>(xs: Rc<Vec<T>>, predicate: impl Fn(T) -> bool + Clone) -> i64 {
    fold_list(xs.clone(), 0, |count, item| match predicate(item.clone()) {
        true => (count.clone() + 1),
        false => count.clone(),
    })
}

pub fn count_equal<T: Clone>(xs: Rc<Vec<T>>, item: T, eq: impl Fn(T, T) -> bool + Clone) -> i64 {
    count_where(xs.clone(), |candidate| eq(candidate.clone(), item.clone()))
}

pub fn unique<T: Clone>(xs: Rc<Vec<T>>, eq: impl Fn(T, T) -> bool + Clone) -> bool {
    {
        let state = fold_list(
            xs.clone(),
            Rc::new(FreeMonoidUniqueState {
                seen: Rc::new(vec![]),
                unique: true,
                _phantom: std::marker::PhantomData,
            }),
            |acc, item| match acc.unique.clone() {
                true => match count_equal(acc.seen.clone(), item.clone(), eq.clone()) {
                    0 => Rc::new(FreeMonoidUniqueState {
                        seen: Rc::new({
                            let mut __cons_v = (*acc.seen.clone()).clone();
                            __cons_v.insert(0, item.clone());
                            __cons_v
                        }),
                        unique: true,
                        _phantom: std::marker::PhantomData,
                    }),
                    _ => Rc::new(FreeMonoidUniqueState {
                        seen: acc.seen.clone(),
                        unique: false,
                        _phantom: std::marker::PhantomData,
                    }),
                },
                false => acc.clone(),
            },
        );
        state.unique.clone()
    }
}

pub fn list_append<T: Clone>(left: Rc<Vec<T>>, right: Rc<Vec<T>>) -> Rc<Vec<T>> {
    fold_list_right(left.clone(), right.clone(), |acc, item| {
        Rc::new({
            let mut __cons_v = (*acc.clone()).clone();
            __cons_v.insert(0, item.clone());
            __cons_v
        })
    })
}

pub fn list_snoc_item<T: Clone>(xs: Rc<Vec<T>>, item: T) -> Rc<Vec<T>> {
    list_append(
        xs.clone(),
        Rc::new({
            let mut __cons_v = (*Rc::new(vec![])).clone();
            __cons_v.insert(0, item.clone());
            __cons_v
        }),
    )
}

