pub fn list_init<T: Clone>(xs: Rc<Vec<T>>) -> Rc<Vec<T>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match xs.clone() {
        FreeMonoid::Empty => Rc::new(vec![]),
        FreeMonoid::Cons { ref tail, .. } if matches!(tail.as_ref(), FreeMonoid::Empty) => {
            let FreeMonoid::Empty = tail.as_ref() else {
                unreachable!()
            };
            Rc::new(vec![])
        }
        FreeMonoid::Cons {
            head: h, tail: t, ..
        } => Rc::new({
            let mut __cons_v = (*list_init(t.clone())).clone();
            __cons_v.insert(0, h.clone());
            __cons_v
        }),
    })
}

