pub fn bag_eq<T: Clone>(xs: Rc<Vec<T>>, ys: Rc<Vec<T>>, eq: impl Fn(T, T) -> bool + Clone) -> bool {
    if (length(xs.clone()) != length(ys.clone())) {
        false
    } else {
        for_all(xs.clone(), |item| {
            (count_equal(xs.clone(), item.clone(), eq.clone())
                == count_equal(ys.clone(), item.clone(), eq.clone()))
        })
    }
}

pub fn zip_eq<T: Clone>(a: Rc<Vec<T>>, b: Rc<Vec<T>>, eq: impl Fn(T, T) -> bool + Clone) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match a.clone() {
        FreeMonoid::Empty => match b.clone() {
            FreeMonoid::Empty => true,
            FreeMonoid::Cons { .. } => false,
        },
        FreeMonoid::Cons {
            head: ha, tail: ta, ..
        } => match b.clone() {
            FreeMonoid::Empty => false,
            FreeMonoid::Cons {
                head: hb, tail: tb, ..
            } => (eq(ha.clone(), hb.clone()) && zip_eq(ta.clone(), tb.clone(), eq.clone())),
        },
    })
}

pub fn zip_map<A: Clone, B: Clone, C>(
    a: Rc<Vec<A>>,
    b: Rc<Vec<B>>,
    f: impl Fn(A, B) -> C + Clone,
) -> Rc<Vec<C>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match a.clone() {
        FreeMonoid::Empty => Rc::new(vec![]),
        FreeMonoid::Cons {
            head: ha, tail: ta, ..
        } => match b.clone() {
            FreeMonoid::Empty => Rc::new(vec![]),
            FreeMonoid::Cons {
                head: hb, tail: tb, ..
            } => Rc::new({
                let mut __cons_v = (*zip_map(ta.clone(), tb.clone(), f.clone())).clone();
                __cons_v.insert(0, f(ha.clone(), hb.clone()));
                __cons_v
            }),
        },
    })
}

pub fn reduce_or<T: Clone>(xs: Rc<Vec<T>>, fallback: T, combine: impl Fn(T, T) -> T + Clone) -> T {
    match xs.clone() {
        FreeMonoid::Empty => fallback,
        FreeMonoid::Cons {
            head: h, tail: t, ..
        } => fold_non_empty(h.clone(), t.clone(), combine.clone()),
    }
}

pub fn is_prefix_of<T: Clone>(
    prefix: Rc<Vec<T>>,
    xs: Rc<Vec<T>>,
    eq: impl Fn(T, T) -> bool + Clone,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match prefix.clone() {
        FreeMonoid::Empty => true,
        FreeMonoid::Cons {
            head: h_prefix,
            tail: t_prefix,
            ..
        } => match xs.clone() {
            FreeMonoid::Empty => false,
            FreeMonoid::Cons {
                head: h_xs,
                tail: t_xs,
                ..
            } => {
                (eq(h_prefix.clone(), h_xs.clone())
                    && is_prefix_of(t_prefix.clone(), t_xs.clone(), eq.clone()))
            }
        },
    })
}

